class AbTestSettingsInput(TypedDict, total=False):
    versions: Required[list[AbTestSettingsInputVersion]]
    """Versions 2 to 4. Version 1 is the campaign's own `content`."""
    testPercent: Required[int]
    """The share of the audience, in percent, the versions go to, split evenly between them. The rest get the winner."""
    winnerBy: NotRequired[Literal["clicks", "opens", "conversions"]]
    """How the winner is picked: the version with the highest click or open rate over its delivered messages (as the campaign's own rates; over sent until any version has a delivery), or the highest share of its sent messages that reached the campaign's conversion goal (`conversionGoalId`). Opens overcount: machine opens (Apple Mail Privacy Protection, Gmail's prefetch, mail scanners) count unread email as opened. A push test is decided by clicks (a tap the app reports with a link to follow, so the push needs an `actionUrl`) or conversions, not opens. A tie goes to the lower version."""
    conversionGoalId: NotRequired[str]
    """The campaign's conversion goal that decides; required when `winnerBy` is `conversions`."""
    decideAfter: Required[Optional[DurationInput]]
    """How long after the test went out to pick the winner and send it to the rest, from 1 to 72 hours; `null` to pick it by hand."""


